UPDATE public.question_keys SET explanation = 'The text first explains the advantage of large size, then shows how introduced rats turned that advantage into a liability.', updated_at = NOW() WHERE question_id = 'RW-M10P-0252';
UPDATE public.question_keys SET explanation = 'The keyed choice accurately captures the central claim: warming temperatures enable tropical herbivorous fish to move into temperate kelp habitats, where their grazing outpaces kelp regrowth and converts dense canopies into sparse reefs. The other choices introduce claims unsupported by the passage.', updated_at = NOW() WHERE question_id = 'RW-INF-001';
UPDATE public.question_keys SET explanation = 'To support the claim that the pairing captures nearly the full weed-suppression benefit of the cereal grass without sacrificing the legume''s nitrogen retention, The keyed choice directly cites the 50/50 mix''s metrics (86% and 64 kg/ha) alongside the single-crop benchmarks (89% and 68 kg/ha).', updated_at = NOW() WHERE question_id = 'RW-INF-003';
UPDATE public.question_keys SET explanation = 'The keyed choice directly shows railway scheduling (''six-minute intervals of the junction bell'') reshaping a character''s intimate emotional and familial perception (''measuring his father''s pauses... as though affection itself were a connection to be missed'').', updated_at = NOW() WHERE question_id = 'RW-INF-004';
UPDATE public.question_keys SET explanation = 'The keyed choice synthesizes all parts of the prompt: acknowledging the lower energy density, explaining why weight is unimportant for stationary storage, and highlighting both cold-weather retention (>88% at -20°C) and abundant sodium materials.', updated_at = NOW() WHERE question_id = 'RW-EXP-002';
UPDATE public.question_keys SET explanation = 'The keyed choice explicitly states the engineering trade-off: halving the speed from 33 1/3 rpm to 16 2/3 rpm doubled the audio capacity while sacrificing some high-frequency fidelity.', updated_at = NOW() WHERE question_id = 'RW-EXP-003';
